def record(
    country: str,
    name: str,
    name_cn: str,
    asset_type: str,
    lat: float | None,
    lon: float | None,
    *,
    value: str | None = None,
    metric_type: str = "undisclosed",
    unit: str | None = None,
    data_date: str | None = None,
    status: str = "公开命名资产",
    source: str,
    source_url: str | None = None,
    note: str = "",
) -> dict[str, Any]:
    return {
        "country": country,
        "name": name,
        "name_cn": name_cn,
        "asset_type": asset_type,
        "lat": lat,
        "lon": lon,
        "value": value,
        "metric_type": metric_type,
        "unit": unit,
        "data_date": data_date,
        "status": status,
        "coordinate_precision": "近似中心点" if lat is not None and lon is not None else "待核验；仅列目录",
        "source": source,
        "source_url": source_url or SOURCES[source],
        "note": note,
    }

